import{_ as s,c as n,o as e,aN as t}from"./chunks/framework.DUf1V_IZ.js";const b=JSON.parse('{"title":"ARP","description":"","frontmatter":{"date":"2026-08-05T16:15:00.000Z","title":"ARP","permalink":"/pages/5a6b7c","categories":["Protocol","网络层协议"]},"headers":[],"relativePath":"Protocol/03.网络层协议/02.arp.md","filePath":"Protocol/03.网络层协议/02.arp.md","lastUpdated":1785924051000}'),r={name:"Protocol/03.网络层协议/02.arp.md"};function l(p,a,o,i,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="arp-协议" tabindex="-1">ARP 协议 <a class="header-anchor" href="#arp-协议" aria-label="Permalink to &quot;ARP 协议&quot;">​</a></h1><p>ARP（Address Resolution Protocol，<strong>地址解析协议</strong>）用于把 <strong>IP 地址解析为 MAC 地址</strong>（也就是「已知对端 IP，求对端网卡硬件地址」）。它工作在 <strong>TCP/IP 模型的网络接口层 / 链路层与网络层交界处</strong>（严格说属于链路层，但为配合 IP 通信而存在），是局域网通信不可或缺的一环。</p><blockquote><p>为什么需要它？网络层用 IP 寻址（逻辑地址），但数据帧在**二层（以太网）**实际是靠 <strong>MAC 地址</strong> 投递的。发包前必须知道下一跳/目的主机的 MAC，ARP 就是做这个「翻译」。</p></blockquote><hr><h2 id="一、arp-的工作流程" tabindex="-1">一、ARP 的工作流程 <a class="header-anchor" href="#一、arp-的工作流程" aria-label="Permalink to &quot;一、ARP 的工作流程&quot;">​</a></h2><p>假设主机 A（192.168.1.10）要给同网段主机 B（192.168.1.20）发包，但只知道 B 的 IP：</p><ol><li><strong>查缓存</strong>：A 先看本地 <strong>ARP 缓存表</strong> 是否已有 192.168.1.20 → MAC 的映射，有则直接用。</li><li><strong>ARP 请求（广播）</strong>：没有缓存时，A 在局域网内<strong>广播</strong>一个 ARP Request：「谁的 IP 是 192.168.1.20？请把你的 MAC 告诉我」。</li><li><strong>ARP 应答（单播）</strong>：只有 B 认领该 IP，向 A <strong>单播</strong>回 ARP Reply，带上自己的 MAC。</li><li><strong>写缓存</strong>：A 把 <code>192.168.1.20 ↔ MAC</code> 写入 ARP 缓存（有老化时间，通常几分钟），之后直接通信。</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A ──广播──&gt; [ 谁有 192.168.1.20？ ] ──&gt; 全网</span></span>
<span class="line"><span>B ──单播──&gt; [ 我是 192.168.1.20，MAC=xx:xx ] ──&gt; A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>跨网段时：A 发现目标不在同一子网，会把包发给<strong>默认网关</strong>的 MAC（同样通过 ARP 解析网关 IP），由路由器转发——所以「跨网段通信」依然要先 ARP 到网关。</p><hr><h2 id="二、报文格式-以太网-arp" tabindex="-1">二、报文格式（以太网 ARP） <a class="header-anchor" href="#二、报文格式-以太网-arp" aria-label="Permalink to &quot;二、报文格式（以太网 ARP）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>| 硬件类型(1=以太网) | 协议类型(0x0800=IPv4) |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>| 硬件地址长度(6)  | 协议地址长度(4)  |     操作 Opcode          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                    发送方 MAC（6 字节）                     |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|               发送方 IP（4 字节）                        |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                    目标 MAC（6 字节）                     |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|               目标 IP（4 字节）                         |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><ul><li><strong>操作 Opcode</strong>：<code>1</code> = ARP 请求（Request），<code>2</code> = ARP 应答（Reply）。请求时「目标 MAC」填全 0（未知）。</li><li>硬件类型 <code>1</code> 表示以太网；协议类型 <code>0x0800</code> 表示要解析的是 IPv4 地址。</li></ul><hr><h2 id="三、arp-缓存与常用命令" tabindex="-1">三、ARP 缓存与常用命令 <a class="header-anchor" href="#三、arp-缓存与常用命令" aria-label="Permalink to &quot;三、ARP 缓存与常用命令&quot;">​</a></h2><ul><li>缓存条目有过期时间，超时或 IP 变更后会重新解析。</li><li>查看/管理缓存： <ul><li>Windows / Linux：<code>arp -a</code>（查看）；<code>arp -d</code>（删除某条）。</li><li>Linux 还可：<code>ip neigh</code>（更现代的邻居表查看）。</li></ul></li></ul><hr><h2 id="四、安全-arp-欺骗-arp-毒化" tabindex="-1">四、安全：ARP 欺骗（ARP 毒化） <a class="header-anchor" href="#四、安全-arp-欺骗-arp-毒化" aria-label="Permalink to &quot;四、安全：ARP 欺骗（ARP 毒化）&quot;">​</a></h2><p>ARP 本身<strong>没有认证</strong>，任何主机都能声称「我是 192.168.1.1（网关）」。攻击者据此伪造 ARP 应答，把自己伪装成网关/受害者，实现：</p><ul><li><strong>中间人攻击（MITM）</strong>：劫持、窃听、篡改局域网内流量。</li><li><strong>断网/黑洞</strong>：伪造映射使流量发往不存在的 MAC。</li></ul><p>防护手段：静态 ARP 绑定、交换机端口安全 / DHCP Snooping + 动态 ARP 检测（DAI）、网络分段与加密（HTTPS/VLAN）。</p><hr><h2 id="五、相关协议" tabindex="-1">五、相关协议 <a class="header-anchor" href="#五、相关协议" aria-label="Permalink to &quot;五、相关协议&quot;">​</a></h2><ul><li><strong>RARP</strong>：反向 ARP，由 MAC 求 IP（已被 BOOTP/DHCP 取代）。</li><li><strong>代理 ARP</strong>：路由器代答 ARP，让不同子网主机「以为」在同一网段。</li><li><strong>IPv6 的 NDP</strong>：IPv6 不再使用 ARP，而是用 <strong>NDP（邻居发现协议，基于 ICMPv6）</strong> 完成地址解析、重复地址检测等。</li></ul><hr><h2 id="六、与-icmp-tcp-的层次关系" tabindex="-1">六、与 ICMP / TCP 的层次关系 <a class="header-anchor" href="#六、与-icmp-tcp-的层次关系" aria-label="Permalink to &quot;六、与 ICMP / TCP 的层次关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>层次</th><th>职责</th></tr></thead><tbody><tr><td>ARP</td><td>链路层 / 网络层交界</td><td>IP ↔ MAC 地址解析</td></tr><tr><td>ICMP</td><td>网络层（L3）</td><td>差错与控制报文（ping/traceroute）</td></tr><tr><td>TCP / UDP</td><td>传输层（L4）</td><td>端到端可靠/不可靠传输</td></tr></tbody></table><blockquote><p>简单记忆：要发包先靠 <strong>ARP</strong> 找到 MAC（二层），要诊断网络靠 <strong>ICMP</strong>（三层），要传数据靠 <strong>TCP/UDP</strong>（四层）。</p></blockquote>`,28)])])}const u=s(r,[["render",l]]);export{b as __pageData,u as default};
